/* Auth gate - the report endpoint reads platform health and can mint a
   no-login share link, so it is never anonymous. */
const req = $input.first().json;
const headers = req.headers || {};
const expected = $env.CHAT_API_KEY;
const provided = String(headers.authorization || '').replace(/^Bearer\s+/i, '');
if (!expected || provided !== expected) {
  return [{ json: { __error: true, status: 401, body: { error: { message: 'Invalid API key. Provide it via the Authorization: Bearer header.', type: 'authentication_error', code: 'invalid_api_key' } } } }];
}
return [{ json: { ok: true } }];

/* Health report: turn the newest selfcheck run into a document a client can open.

   Why: every acceptance report in monitoring/*.md was written by hand, while
   selfcheck already persists its full result set in selfcheck_runs.report.
   Rendering that instead of retyping it makes the report reproducible and
   costs one webhook call.

   Two audiences, deliberately:
     internal - every assertion with its detail, internal hostnames included.
     client   - group-level counts and a verdict ONLY. No check names, no
                details, so there is structurally nothing to leak. The text is
                still run through a denylist and the document is NOT created if
                anything matches (fail closed): a future edit that adds details
                to the client version cannot silently ship them.

   An optional project (slug or label from the projects registry) is resolved
   against the registry, prefixed onto the title, stored on the document, and
   joins the scrub target -- a label is caller-influenced data like the title.

   Signing (the 7-day no-login link) defaults to ON for client and OFF for
   internal -- an internal report behind a bearer-free URL would be the leak
   this whole split exists to prevent. */
const req = $('Webhook Report').first().json;
const body = (req && req.body) || {};
const NL = String.fromCharCode(10);
const AUTH = ['Bea', 'rer '].join('') + ($env.CHAT_API_KEY || '');
const N8N = 'http://localhost:5678';
const H = { Authorization: AUTH, 'Content-Type': 'application/json' };

const api = (method, path, qs, payload) => this.helpers.httpRequest({
  method, url: N8N + '/api/v1' + path,
  headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY, 'Content-Type': 'application/json' },
  qs, body: payload, timeout: 25000,
});
const forge = async (payload) => this.helpers.httpRequest({
  method: 'POST', url: N8N + '/webhook/admin/docforge', headers: H, body: payload, timeout: 60000,
});
const err = (status, code, message) => [{ json: { __error: true, status, body: { error: { message: String(message).slice(0, 300), type: 'invalid_request_error', code } } } }];

/* ---- parameters ---- */
const audience = String(body.audience || '').toLowerCase() === 'client' ? 'client' : 'internal';
const maxAgeH = Number(body.max_age_hours) > 0 ? Number(body.max_age_hours) : 24;
const force = body.force === true;
const wantSign = body.sign === undefined ? audience === 'client' : body.sign === true;
const wantPush = body.push === true;
const to = String(body.to || '').trim().replace(/^@/, '');
const ttlDays = Number(body.ttl_days) > 0 ? Number(body.ttl_days) : 7;
const projectArg = String(body.project || '').trim();

const SHIFT = 8 * 3600000;
const cn = (iso) => {
  const t = Date.parse(iso || '');
  return Number.isFinite(t) ? new Date(t + SHIFT).toISOString().slice(0, 16).replace('T', ' ') : '';
};

/* ---- 1. pick the run ---- */
const tables = (await api('GET', '/data-tables', { limit: 100 })).data || [];
const runsId = (tables.find((t) => t.name === 'selfcheck_runs') || {}).id;
if (!runsId) return err(500, 'table_missing', 'selfcheck_runs 表不存在，先跑 n8n/scripts/deploy.mjs');
/* A: resolve the project before doing any work, so a bad slug fails fast and
   the report can never invent a project nobody registered. */
const projectsId = (tables.find((t) => t.name === 'projects') || {}).id;
let projectRef = '';
let projectLabel = '';
if (projectArg) {
  if (!projectsId) return err(500, 'table_missing', 'projects 表不存在，先跑 n8n/scripts/deploy.mjs');
  const projects = (await api('GET', '/data-tables/' + projectsId + '/rows', { limit: 200 })).data || [];
  const lower = (s) => String(s || '').trim().toLowerCase();
  const proj = projects.find((p) => lower(p.name) === lower(projectArg) || lower(p.label) === lower(projectArg));
  if (!proj) return err(400, 'unknown_project', '未登记的项目：' + projectArg + '；先用 n8n/scripts/seed-projects.mjs 登记');
  if (String(proj.status || 'active') === 'archived') return err(400, 'project_archived', '项目已归档：' + proj.name);
  projectRef = proj.name;
  projectLabel = proj.label || proj.name;
}

const runs = (await api('GET', '/data-tables/' + runsId + '/rows', { limit: 250 })).data || [];
if (!runs.length) return err(404, 'no_selfcheck_run', '还没有任何自检记录；先跑一次 POST /webhook/admin/selfcheck/run');

const stampOf = (r) => Date.parse(r.checked_at || r.createdAt || '') || 0;
let row = null;
if (body.run_id) {
  row = runs.find((r) => Number(r.id) === Number(body.run_id)) || null;
  if (!row) return err(404, 'run_not_found', 'run_id ' + body.run_id + ' 不在最近 250 条自检记录里');
} else {
  row = runs.slice().sort((a, b) => stampOf(b) - stampOf(a))[0];
}

/* ---- 2. parse the persisted detail ---- */
let checks = [];
let truncated = false;
try {
  const parsed = JSON.parse(String(row.report || ''));
  checks = Array.isArray(parsed.checks) ? parsed.checks : [];
} catch (eParse) {
  /* report is capped at 18000 chars when selfcheck writes it, so a long run can
     arrive cut in half. Counts still come from the row's own columns. */
  truncated = String(row.report || '').length >= 17000;
  checks = [];
}
const total = Number(row.total || checks.length || 0);
const passed = Number(row.passed || 0);
const failed = Number(row.failed || 0);
const warned = Number(row.warned || 0);
const durationMs = Number(row.duration_ms || 0);
const checkedAt = String(row.checked_at || row.createdAt || '');
const source = String(row.source || '');

/* ---- 3. freshness: a stale run must not become a client document ---- */
const ageH = Number.isFinite(stampOf(row)) ? (Date.now() - stampOf(row)) / 3600000 : NaN;
if (!(ageH <= maxAgeH) && !force) {
  return err(409, 'stale_selfcheck', '最近一次自检是 ' + cn(checkedAt) + '（' + (Number.isFinite(ageH) ? ageH.toFixed(1) : '?') + ' 小时前），超过 ' + maxAgeH + 'h；先重跑自检，或传 force:true / max_age_hours 明确接受旧数据');
}

/* ---- 4. group aggregation ---- */
const GROUPS = [
  { key: 'infra', label: '基础设施' },
  { key: 'gateway', label: '对话网关' },
  { key: 'stream', label: '流式通道' },
  { key: 'channel', label: '推送通道' },
  { key: 'data', label: '数据与业务' },
];
const agg = {};
for (const g of GROUPS) agg[g.key] = { total: 0, passed: 0, warned: 0, failed: 0 };
agg.other = { total: 0, passed: 0, warned: 0, failed: 0 };
for (const c of checks) {
  const k = agg[c.group] ? c.group : 'other';
  agg[k].total += 1;
  if (!c.ok) agg[k].failed += 1;
  else if (c.warn) agg[k].warned += 1;
  else agg[k].passed += 1;
}
const groupRows = GROUPS.filter((g) => agg[g.key].total > 0).map((g) => Object.assign({ key: g.key, label: g.label }, agg[g.key]));
if (agg.other.total) groupRows.push(Object.assign({ key: 'other', label: '其他' }, agg.other));

const verdict = failed > 0
  ? '存在未通过项（' + failed + ' 项），处理后才适合交付'
  : (warned > 0 ? '全部通过，其中 ' + warned + ' 项处于降级状态' : '全部通过');
const icon = (c) => (!c.ok ? '❌' : (c.warn ? '🔵' : '✅'));

/* ---- 5. render ---- */
const summaryLines = [
  '- 断言 ' + total + ' 项：通过 ' + passed + ' / 警告 ' + warned + ' / 失败 ' + failed,
  '- 结论：' + verdict,
  '- 自检时间 ' + cn(checkedAt) + '（北京时间）· 耗时 ' + (durationMs / 1000).toFixed(1) + ' 秒 · 触发方式 ' + (source || '未知'),
];

let text;
if (audience === 'client') {
  /* Group level only. Check names are omitted on purpose: they carry component
     names (stream-bridge, searxng, ...) that describe the internal topology. */
  const L = ['【总体结论】'];
  summaryLines.forEach((x) => L.push(x));
  L.push('【分组结果】');
  if (groupRows.length) {
    groupRows.forEach((g) => {
      const mark = g.failed ? '❌' : (g.warned ? '🔵' : '✅');
      L.push('- ' + mark + ' ' + g.label + '：' + g.total + ' 项' + (g.failed || g.warned ? '（通过 ' + g.passed + (g.warned ? ' / 警告 ' + g.warned : '') + (g.failed ? ' / 失败 ' + g.failed : '') + '）' : '全部通过'));
    });
  } else {
    L.push('- 🔵 明细不可用（自检记录被截断），仅提供上面的总体结论');
  }
  L.push('【说明】');
  L.push('- 警告＝能力可用但处于降级状态；失败＝该项能力当前不可用');
  L.push('- 未通过项的具体原因记录在内部版报告中，不在此文档列出');
  if (truncated || !checks.length) L.push('- 本次报告的明细分组不可用，结论以自检汇总计数为准');
  L.push('——本报告由平台自检自动产出，可复现，非人工填写');
  text = L.join(NL);
} else {
  const L = ['【摘要】'];
  summaryLines.forEach((x) => L.push(x));
  L.push('- 距今 ' + (Number.isFinite(ageH) ? ageH.toFixed(1) + ' 小时' : '未知') + (force && !(ageH <= maxAgeH) ? '（已用 force 越过新鲜度守卫）' : ''));
  L.push('【分组】');
  groupRows.forEach((g) => L.push('- ' + g.key + ' ' + g.label + '：' + g.total + ' 项（通过 ' + g.passed + ' / 警告 ' + g.warned + ' / 失败 ' + g.failed + '）'));
  const fails = checks.filter((c) => !c.ok);
  const warns = checks.filter((c) => c.ok && c.warn);
  if (fails.length) {
    L.push('【失败项】');
    fails.forEach((c) => L.push('- [' + c.group + '] ' + c.name + ' — ' + String(c.detail || '').slice(0, 240) + '（' + c.ms + 'ms）'));
  }
  if (warns.length) {
    L.push('【警告项】');
    warns.forEach((c) => L.push('- [' + c.group + '] ' + c.name + ' — ' + String(c.detail || '').slice(0, 240)));
  }
  if (checks.length) {
    L.push('【全部断言】');
    checks.forEach((c) => L.push('- ' + icon(c) + ' [' + c.group + '] ' + c.name + '（' + c.ms + 'ms）'));
  } else {
    L.push('【全部断言】');
    L.push('- 🔵 明细缺失：selfcheck_runs.report ' + (truncated ? '被 18000 字符上限截断' : '为空或无法解析') + '，仅汇总计数可用');
  }
  L.push('——来源：selfcheck_runs #' + row.id + '（' + (source || '未知') + '）· 由 health-report 渲染');
  text = L.join(NL);
}

/* ---- 6. scrub the client version, fail closed ---- */
let scrubbed = null;
if (audience === 'client') {
  const DENY = [
    /localhost/i, /127\.0\.0\.1/, /0\.0\.0\.0/, /\b192\.168\./, /\b10\.\d+\./, /\b172\.(1[6-9]|2\d|3[01])\./,
    /:\d{4,5}\b/, /https?:\/\//i,
    /n8n-sandbox/i, /stream-bridge/i, /searxng/i, /minio/i, /rustfs/i, /lobechat/i, /lobehub/i,
    /postgres/i, /paradedb/i, /redis/i, /platform-runtime/i, /platform-worker/i, /\bcaddy\b/i, /kafka/i, /prometheus/i,
    /_KEY\b/, /_SECRET\b/, /_TOKEN\b/, /_PASSWORD\b/, /\bCHAT_API\b/, /\bN8N_API\b/,
    /selfcheck_runs/i, /data-tables/i, /\/webhook\//i, /docker/i, /\bcompose\b/i,
    /[A-Za-z]:\\/, /\/app\//, /\/home\/node\//,
  ];
  /* The caller-supplied title and the resolved project label are scrubbed too:
     both land in the document title and in the share message, so an internal
     hostname pasted there would ride out on an otherwise clean report. */
  const scrubTarget = String(body.title || '') + NL + projectLabel + NL + text;
  const hits = DENY.filter((re) => re.test(scrubTarget)).map((re) => String(re));
  if (hits.length) {
    return err(500, 'scrub_failed', '对外版报告命中脱敏黑名单 ' + hits.length + ' 条（' + hits.slice(0, 4).join(' ') + '），已拒绝生成文档；修掉渲染逻辑再试');
  }
  scrubbed = { checked: DENY.length, hits: 0 };
}

/* ---- 7. create / sign / push ---- */
const title = (projectLabel ? projectLabel + ' · ' : '') + String(body.title || (audience === 'client' ? '平台健康验收报告' : '平台自检内部报告')).slice(0, 80) + ' · ' + cn(checkedAt);
let created;
try {
  created = await forge({ action: 'create', kind: 'custom', title, text, project: projectRef || undefined });
} catch (eCreate) {
  return err(502, 'docforge_create_failed', String((eCreate && eCreate.message) || eCreate).slice(0, 200));
}
if (!created || created.ok !== true || !created.id) {
  return err(502, 'docforge_create_failed', 'doc-forge 没有返回文档 id：' + JSON.stringify(created || {}).slice(0, 200));
}

let url = null;
let expiresInDays = null;
if (wantSign) {
  try {
    const s = await forge({ action: 'sign', id: created.id, ttl_seconds: ttlDays * 86400 });
    if (s && s.ok) { url = s.url; expiresInDays = s.expires_in_days; }
  } catch (eSign) { url = null; }
}

let pushed = null;
if (wantPush) {
  try {
    const sh = await forge({ action: 'share', id: created.id, to: to || undefined });
    pushed = { to: (sh && sh.to) || '(机主)', delivered: !!(sh && sh.delivered), degraded: !!(sh && sh.degraded) };
    if (!url && sh && sh.url) { url = sh.url; expiresInDays = ttlDays; }
  } catch (ePush) {
    pushed = { to: to || '(机主)', delivered: false, degraded: false, error: String((ePush && ePush.message) || ePush).slice(0, 120) };
  }
}

return [{ json: {
  ok: true,
  audience,
  project: projectRef || null,
  project_label: projectLabel || null,
  run_id: row.id,
  checked_at: checkedAt,
  age_hours: Number.isFinite(ageH) ? Number(ageH.toFixed(2)) : null,
  stale_but_forced: !!(force && !(ageH <= maxAgeH)),
  source,
  total, passed, warned, failed,
  duration_ms: durationMs,
  verdict,
  groups: groupRows,
  detail_available: checks.length > 0,
  report_truncated: truncated,
  doc_id: created.id,
  title,
  chars: created.chars || null,
  url,
  expires_in_days: expiresInDays,
  pushed,
  scrub: scrubbed,
} }];
